function drawKecleonChameleon(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.3;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 2.8;

  const tailWiggle = Math.sin(t * 2.5) * 2.0;
  const eyeMoveX = Math.sin(t * 3.5) * 2.0;
  const eyeMoveY = Math.cos(t * 3.5) * 2.0;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(-2, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Đuôi xoắn
  const tx = 18 + tailWiggle;
  ctx.fillStyle = '#22c55e';
  ctx.beginPath(); ctx.arc(tx, by + 16, 10, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#15803d';
  ctx.beginPath(); ctx.arc(tx + 2, by + 16, 6, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#22c55e';
  ctx.beginPath(); ctx.arc(tx + 2, by + 16, 3, 0, Math.PI * 2); ctx.fill();

  // 3. Thân
  ctx.beginPath(); ctx.ellipse(-2, by + 12, 14 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // 4. Zigzag đỏ
  ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(-12, by + 12); ctx.lineTo(-8, by + 16);
  ctx.lineTo(-4,  by + 12); ctx.lineTo(0,  by + 16);
  ctx.lineTo(4,   by + 12); ctx.lineTo(8,  by + 16);
  ctx.stroke();

  // 5. Chân
  ctx.fillStyle = '#22c55e';
  ctx.beginPath(); ctx.roundRect(-14, by + 24, 6, 12, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(4,   by + 24, 6, 12, 2); ctx.fill();

  // 6. Đầu
  ctx.beginPath(); ctx.arc(-6, by - 8, 16 * sX, 0, Math.PI * 2); ctx.fill();

  // 7. Mào vàng & Mỏ
  ctx.fillStyle = '#facc15';
  ctx.beginPath();
  ctx.moveTo(-14, by - 16); ctx.lineTo(-18, by - 32); ctx.lineTo(-6, by - 20);
  ctx.lineTo(0,   by - 34); ctx.lineTo(4,   by - 18);
  ctx.fill();
  ctx.beginPath(); ctx.roundRect(-22, by - 6, 16, 5, 2); ctx.fill();

  // 8. Mắt
  ctx.beginPath(); ctx.arc(-4, by - 10, 7, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#22c55e';
  ctx.beginPath(); ctx.arc(-4, by - 10, 5, 0, Math.PI * 2); ctx.fill();
  if (!blink) {
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.arc(-4 + eyeMoveX, by - 10 + eyeMoveY, 2, 0, Math.PI * 2); ctx.fill();
  }

  ctx.restore();
}
